function validate([coins, k]) {
  if (coins.length < 1 || coins.length > 100000) return 'coins needs 1 to 10^5 segments.';
  if (k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  for (const segment of coins) {
    if (segment.length !== 3) return 'Each segment is [l, r, c].';
    const [l, r, c] = segment;
    if (l < 1 || l > r || r > 1000000000) return 'Each segment needs 1 <= l <= r <= 10^9.';
    if (c < 1 || c > 1000) return 'Each c is between 1 and 1000.';
  }
  const sorted = [...coins].sort((a, b) => a[0] - b[0]);
  for (let i = 1; i < sorted.length; i++) if (sorted[i][0] <= sorted[i - 1][1]) return 'Segments must not overlap.';
  return null;
}

