function maximumCoins(coins, k) {
  // Best total over windows whose last bag is the right end of some segment.
  const rightAligned = segments => {
    segments.sort((a, b) => a[0] - b[0]);
    let best = 0;
    let cover = 0;
    let left = 0;
    for (const [start, end, count] of segments) {
      cover += (end - start + 1) * count;
      const windowStart = end - k + 1;
      while (segments[left][1] < windowStart) {
        cover -= (segments[left][1] - segments[left][0] + 1) * segments[left][2];
        left++;
      }
      const outside = Math.max(0, windowStart - segments[left][0]) * segments[left][2];
      best = Math.max(best, cover - outside);
    }
    return best;
  };

  // Mirroring turns windows that start at some l_i into windows that end at a right end.
  const mirrored = coins.map(([start, end, count]) => [-end, -start, count]);
  return Math.max(rightAligned(coins), rightAligned(mirrored));
}

