function maximumCoins(coins, k) {
  // The total changes at a constant rate between these starts, so one of them is a best start.
  const starts = coins.flatMap(([l, r]) => [l, r + 1, l - k, r - k + 1]);
  let best = 0;
  for (const s of starts) {
    let total = 0;
    for (const [l, r, c] of coins) {
      const overlap = Math.min(r, s + k - 1) - Math.max(l, s) + 1;
      if (overlap > 0) total += overlap * c;
    }
    best = Math.max(best, total);
  }
  return best;
}

