function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 : 1 + pick(5);
  // Segments are laid out left to right with random gaps (sometimes none), then shuffled.
  const maxGap = large ? [0, 1000, 200000][pick(3)] : [0, 1, 4][pick(3)];
  const maxLength = large ? [1, 1000, 250000][pick(3)] : [1, 3, 8][pick(3)];
  const maxCount = large ? 1000 : [3, 1000][pick(2)];
  const coins = [];
  let position = 1 + pick(maxGap + 1);
  for (let i = 0; i < n; i++) {
    const length = 1 + pick(maxLength);
    coins.push([position, position + length - 1, 1 + pick(maxCount)]);
    position += length + pick(maxGap + 1);
  }
  for (let i = coins.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [coins[i], coins[j]] = [coins[j], coins[i]];
  }
  // k is tiny, about the size of one segment, about the whole span, or larger than everything.
  const span = position;
  const choice = pick(4);
  const k = choice === 0 ? 1 + pick(3) : choice === 1 ? 1 + pick(maxLength + 2) : choice === 2 ? 1 + pick(span) : large ? 1000000000 : span + pick(5);
  return [coins, k];
}
